class ZipFile::Writer
  attr_reader :byte_size

  def initialize(io = nil)
    @entries = Set.new
    @byte_size = 0
    @output_io = io
    @streamer = nil
    @digest = Digest::MD5.new
  end

  def stream_to(io)
    @output_io = io
  end

  # The streamer writes through this method, so that the size and checksum
  # of the archive are known once it's closed, whatever the destination is.
  def write(data)
    @output_io.write(data)
    @byte_size += data.bytesize
    @digest.update(data)
    data.bytesize
  end

  def add_file(path, content = nil, compress: true)
    write_method = compress ? :write_deflated_file : :write_stored_file

    if block_given?
      streamer.public_send(write_method, path) { |sink| yield sink }
    else
      streamer.public_send(write_method, path) { |sink| sink.write(content) }
    end

    # Only track entries that made it into the archive: the streamer rolls
    # back entries whose block raised.
    @entries << path
  end

  def glob(pattern)
    @entries.select { |e| File.fnmatch(pattern, e) }.sort
  end

  def exists?(path)
    @entries.include?(path)
  end

  def close
    streamer.close
  end

  def checksum
    Base64.strict_encode64(@digest.digest)
  end

  private
    def streamer
      @streamer ||= ZipKit::Streamer.new(self)
    end
end
